def solve(g):
    g=[row[:] for row in g]
    H=len(g)
    # find separator row
    sep=[r for r,row in enumerate(g) if all(v==5 for v in row)][0]
    up=g[:sep]; bot=g[sep+1:]
    def find(col):
        rows=[r for r,v in enumerate(col) if v!=0]
        return min(rows),max(rows)
    def norm(cells):
        rs=[y for y,x in cells]; cs=[x for y,x in cells]
        return (min(rs),max(rs)),(min(cs),max(cs))
    upcs=[]; botcs=[]
    for r in range(len(up)):
        for c in range(len(up[0])):
            v=up[r][c]
            if v!=0:
                st=[(r,c)]; seen={(r,c)}; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if (ny,nx) not in seen and up[ny][nx]==v:
                            seen.add((ny,nx)); st.append((ny,nx))
                upcs.append((v,sorted(cells)))
    for r in range(len(bot)):
        for c in range(len(bot[0])):
            v=bot[r][c]
            if v!=0:
                st=[(r,c)]; seen={(r,c)}; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if (ny,nx) not in seen and bot[ny][nx]==v:
                            seen.add((ny,nx)); st.append((ny,nx))
                botcs.append((v,sorted(cells)))
    # pair = same color, identical shape normalized, one up one down
    pair=None
    for (v,a) in upcs:
        na=(norm(a))
        for (vv,b) in botcs:
            if vv==v and norm(b)==na:
                pair=(v,a,b)
    assert pair
    v,a,b=pair
    r1,c1,r2,c2=norm(a); r3,c3,r4,c4=norm(b)
    # other comps in top
    others=[(v,cells) for v,cells in upcs if (v,cells)!=a]
    keep=max(others,key=lambda o: o[1][-1][1])  # rightmost
    drop=[o for o in others if o!=keep][0]
    # result grid: combine up/out regions mapped appropriately
    out=[row[:] for row in g]
    # removed top copy and dropped comp; moved pair bottom copy up 6 rows
    hgt=len(g)
    for r in range(hgt):
        for c in range(len(g[0])):
            out[r][c]=0
    # moved pair (bottom copy) up 6, same columns
    for (y,x) in b:
        out[y-6][x]=v
    # kept comp: translate to be flush below the pair, centered on pair columns
    pr_min=min(y for y,x in (y-6 for y,_ in b)); pr_max=max(y for y,_ in (y-6 for y,_ in b))
    pc_min=min(x for _,x in b); pc_max=max(x for _,x in b)
    cc=(pc_min+pc_max)//2
    # kept comp center col -> align with pair center
    cr=(keep[1][0][0]+keep[1][-1][0])//2; cc2=(keep[1][0][1]+keep[1][-1][1])//2
    for (y,x) in keep[1]:
        ny=pr_min+(y-keep[1][0][0]); nx=cc-(cc2-keep[1][0][1])
        out[ny][nx]=keep[0]
    return out

