def norm(cells):
    rs=[r for r,c in cells]; cs2=[c for r,c in cells]
    return tuple(sorted((r-min(rs),c-min(cs2)) for r,c in cells))

def comps_of(g, skip=None):
    H=len(g);W=len(g[0]);R=[[False]*W for _ in range(H)]; out=[]
    for rr in range(H):
        for cc in range(W):
            if R[rr][cc]: continue
            st=g[rr][cc]
            if skip is not None and st in skip: continue
            stack=[(rr,cc)];cells=[];R[rr][cc]=True
            while stack:
                r,c=stack.pop();cells.append((r,c))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    n=(r+dr,c+dc)
                    if 0<=n[0]<H and 0<=n[1]<W and not R[n[0]][n[1]] and g[n[0]][n[1]]==st:
                        R[n[0]][n[1]]=True;stack.append(n)
            out.append((st,cells))
    return out

def f(g):
    # separator row of all 5s
    sep=next(i for i in range(len(g)) if all(x==5 for x in g[i]))
    top=g[:sep]; bot=g[sep+1:]
    sc=comps_of(top); bc=comps_of(bot)
    bykey={}
    for s,cs in sc: bykey.setdefault(norm(cs),[]).append(('t',s,cs))
    for s,cs in bc: bykey.setdefault(norm(cs),[]).append(('b',s,cs))
    res=[]
    for k,v in bykey.items():
