        if len(ts)==1 and len(bs_)==1:
            st,_,ct=ts[0]; sb,_,cb=bs_[0]
            # bottom copy shifted up so its top row = (top top row)-6
            r0=min(r for r,c in ct)
            crs=[r-(r0-6) for r,c in cb]
            c0=min(c for r,c in cb)
            ccols=list(range(c0,max(c for r,c in cb)+1))
            res.append(('P',crs,ccols,(r0,),()))
        else:
            # singletons: keep as-is? or removed? check per demo
